<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import AdvertiserPortalHeader from '@/components/Advertiser/AdvertiserPortalHeader.vue';import{Button}from'@/components/ui/button';const props=defineProps<{advertiser:any;membership:any;campaign:any;creatives:any[]}>();const canEdit=['owner','campaign_manager','creative_contributor'].includes(props.membership.role);</script><template><Head title="Campaign Creatives"/><div class="space-y-6 p-6"><AdvertiserPortalHeader :title="`${campaign.name} Creatives`" description="Upload, edit, and submit creative work for approval." :advertiser="advertiser"><template #actions><Button v-if="canEdit" as-child><Link :href="`/advertiser/campaigns/${campaign.id}/creatives/create`">Add creative</Link></Button></template></AdvertiserPortalHeader><div class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="c in creatives" :key="c.id" class="overflow-hidden rounded-xl border"><div class="aspect-video bg-muted"><img v-if="c.creative_type==='image'" :src="c.media_url" :alt="c.alt_text||c.name" class="h-full w-full object-contain"/><video v-else :src="c.media_url" class="h-full w-full object-contain" controls/></div><div class="space-y-3 p-4"><div class="flex justify-between"><h2 class="font-semibold">{{c.name}}</h2><span class="text-xs uppercase text-muted-foreground">{{c.status}}</span></div><p v-if="c.rejection_reason" class="rounded bg-destructive/10 p-2 text-sm text-destructive">{{c.rejection_reason}}</p><div v-if="canEdit" class="flex gap-2"><Button v-if="c.status!=='approved'" size="sm" variant="outline" as-child><Link :href="`/advertiser/campaigns/${campaign.id}/creatives/${c.id}/edit`">Edit</Link></Button><Button v-if="['draft','rejected'].includes(c.status)" size="sm" @click="router.post(`/advertiser/campaigns/${campaign.id}/creatives/${c.id}/submit`)">Submit</Button></div></div></article><p v-if="!creatives.length" class="col-span-full rounded-xl border p-8 text-center text-muted-foreground">No creatives have been added.</p></div></div></template>
